#include <cassert>
#include "../firmware/family/src/cloud_memory.h"
#include "../firmware/family/src/sensor_logic.h"
int main(){assert(cloudMemoryReady(109656,51188));assert(!cloudMemoryReady(44000,30000));assert(!cloudMemoryReady(120000,16000));StableInput r;assert(!r.update(true,0));assert(!r.update(false,50));assert(!r.update(false,149));assert(r.update(false,150));assert(r.known&&!r.value);assert(!r.update(true,151));assert(!r.update(false,180));assert(!r.update(false,281));assert(!r.value);PumpCounter p;p.tick(true,false,0);p.tick(true,true,100);assert(p.cycles==1);p.tick(true,true,1100);assert(p.milliseconds==1000);p.tick(true,false,2100);assert(p.milliseconds==2000&&p.cycles==1);PumpCounter reboot;reboot.restore(1,2000,true);reboot.tick(true,true,0);assert(reboot.cycles==1);reboot.tick(true,true,1000);assert(reboot.milliseconds==3000);reboot.tick(true,false,1100);reboot.tick(true,true,1200);assert(reboot.cycles==2);PumpCounter wrap;wrap.tick(true,true,0xfffffff0u);wrap.tick(true,true,0x10u);assert(wrap.milliseconds==32);}
